using UnityEngine;
using TMPro;

/// <summary>
/// 道具移除节点 — 玩家靠近显示提示，按 F 打开道具选择面板。
/// 玩家可选择移除一个道具（触发 OnRemove 还原效果），可移除 n 次。
/// </summary>
public class ItemRemover : MonoBehaviour
{
    [Header("配置")]
    [Tooltip("可移除道具的次数（-1=无限）")]
    [SerializeField] private int _removeCount = 1;

    [Header("交互")]
    [Tooltip("交互范围")]
    [SerializeField] private float _interactRadius = 1.5f;
    [Tooltip("交互按键")]
    [SerializeField] private KeyCode _interactKey = KeyCode.F;

    [Header("视觉")]
    [SerializeField] private SpriteRenderer _sr;
    [SerializeField] private Color _normalColor = new Color(0.8f, 0.3f, 0.3f, 1f);
    [SerializeField] private Color _highlightColor = new Color(1f, 0.5f, 0.5f, 1f);
    [SerializeField] private Color _depletedColor = new Color(0.3f, 0.3f, 0.3f, 0.5f);

    [Header("提示文本")]
    [SerializeField] private TMP_Text _promptText;

    private bool _playerInRange;
    private bool _depleted;
    private ItemRemoverPanel _panel;

    private void Awake()
    {
        if (_sr == null)
            _sr = GetComponent<SpriteRenderer>();
        UpdateVisual();
    }

    private void Start()
    {
        _panel = FindObjectOfType<ItemRemoverPanel>(true);
    }

    private void Update()
    {
        if (_depleted) return;

        var player = GameObject.FindGameObjectWithTag("Player");
        if (player == null) return;

        float dist = Vector2.Distance(transform.position, player.transform.position);
        bool inRange = dist <= _interactRadius;

        if (inRange != _playerInRange)
        {
            _playerInRange = inRange;
            UpdateVisual();
            if (_promptText != null)
                _promptText.gameObject.SetActive(inRange);
        }

        if (inRange && Input.GetKeyDown(_interactKey) && _panel != null && !_panel.IsVisible)
        {
            var itemManager = player.GetComponent<ItemManager>();
            if (itemManager != null && itemManager.Count > 0)
            {
                _panel.Show(itemManager, _removeCount, OnPanelClosed);
            }
        }
    }

    private void OnPanelClosed()
    {
        // 面板关闭后检查剩余次数
        if (_panel != null)
        {
            // 读取面板剩余次数（通过反射，避免额外接口）
            var field = typeof(ItemRemoverPanel).GetField("_remainingCount",
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            if (field != null)
            {
                int remaining = (int)field.GetValue(_panel);
                if (_removeCount > 0)
                {
                    _removeCount = remaining;
                    if (_removeCount <= 0)
                    {
                        _depleted = true;
                        UpdateVisual();
                        if (_promptText != null)
                            _promptText.gameObject.SetActive(false);
                    }
                }
            }
        }
    }

    private void UpdateVisual()
    {
        if (_sr == null) return;

        if (_depleted)
            _sr.color = _depletedColor;
        else if (_playerInRange)
            _sr.color = _highlightColor;
        else
            _sr.color = _normalColor;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = new Color(1f, 0.3f, 0.3f, 0.3f);
        Gizmos.DrawWireSphere(transform.position, _interactRadius);
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

/// <summary>
/// 道具移除面板 — 显示玩家当前持有道具列表，点击选择一个移除。
/// 由 ItemRemover 按下 F 键后打开。关闭时恢复游戏交互。
/// </summary>
public class ItemRemoverPanel : MonoBehaviour
{
    [Header("UI 元素")]
    [SerializeField] private TMP_Text _titleText;
    [SerializeField] private TMP_Text _remainingText;
    [SerializeField] private Transform _listContainer;
    [SerializeField] private GameObject _itemEntryPrefab;
    [SerializeField] private Button _closeButton;

    [Header("样式")]
    [SerializeField] private Color _normalColor = new Color(0.12f, 0.12f, 0.16f, 0.95f);

    private ItemManager _itemManager;
    private int _remainingCount;
    private System.Action _onPanelClosed;

    public bool IsVisible => gameObject.activeSelf;

    private void Awake()
    {
        if (_closeButton != null)
            _closeButton.onClick.AddListener(Close);
        gameObject.SetActive(false);
    }

    /// <summary>打开面板，显示玩家道具列表</summary>
    public void Show(ItemManager itemManager, int removeCount, System.Action onPanelClosed = null)
    {
        _itemManager = itemManager;
        _remainingCount = removeCount;
        _onPanelClosed = onPanelClosed;
        gameObject.SetActive(true);
        RefreshList();
    }

    /// <summary>关闭面板</summary>
    public void Close()
    {
        gameObject.SetActive(false);
        _onPanelClosed?.Invoke();
    }

    private void RefreshList()
    {
        // 清空列表
        for (int i = _listContainer.childCount - 1; i >= 0; i--)
            Destroy(_listContainer.GetChild(i).gameObject);

        // 更新标题
        if (_titleText != null)
            _titleText.text = "选择要移除的道具";
        if (_remainingText != null)
            _remainingText.text = _remainingCount > 0
                ? $"剩余移除次数: {_remainingCount}"
                : "移除次数已耗尽";

        if (_itemManager == null || _itemManager.Count == 0)
        {
            if (_titleText != null)
                _titleText.text = "没有可移除的道具";
            return;
        }

        var items = _itemManager.Items;
        foreach (var item in items)
        {
            if (item == null) continue;

            var entry = Instantiate(_itemEntryPrefab, _listContainer);
            SetupEntry(entry, item);
        }
    }

    private void SetupEntry(GameObject entry, ItemData item)
    {
        int count = _itemManager.GetItemCount(item.itemId);

        // Icon
        var icon = entry.transform.Find("Icon")?.GetComponent<Image>();
        if (icon != null)
        {
            icon.sprite = item.icon;
            icon.enabled = item.icon != null;
        }

        // Name
        var nameText = entry.transform.Find("Name")?.GetComponent<TMP_Text>();
        if (nameText != null)
        {
            nameText.text = count > 1 ? $"{item.itemName} x{count}" : item.itemName;
            nameText.color = ItemPickup.QualityToColor(item.quality);
        }

        // Remove button
        var button = entry.GetComponent<Button>();
        if (button == null)
            button = entry.GetComponentInChildren<Button>();

        if (button != null)
        {
            button.onClick.RemoveAllListeners();
            bool canRemove = _remainingCount != 0;
            button.interactable = canRemove;
            button.onClick.AddListener(() =>
            {
                _itemManager.RemoveItem(item.itemId);

                if (_remainingCount > 0)
                {
                    _remainingCount--;
                    if (_remainingCount == 0)
                    {
                        Close();
                        return;
                    }
                }

                if (_itemManager.Count == 0)
                {
                    Close();
                    return;
                }

                RefreshList();
            });
        }
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 道具管理器 — 管理玩家当前持有的所有道具。
/// 挂载在 Player GameObject 上，通过 PlayerManager 的持久化机制自动跟随跨场景。
///
/// 核心职责:
///   1. 管理道具集合（添加/移除/查询/丢弃/转移）
///   2. 执行道具效果（OnAcquire / OnRemove）
///   3. 通知事件（供 UI Controller 监听）
/// </summary>
public class ItemManager : MonoBehaviour
{
    [Header("丢弃配置")]
    [SerializeField] private GameObject _itemDropPrefab; // 丢弃道具时生成的拾取物预制体

    [Header("调试")]
    [SerializeField] private List<ItemData> _initialItems; // Inspector 调试用

    private readonly List<ItemData> _items = new List<ItemData>();
    private readonly Dictionary<string, ItemData> _itemDict = new Dictionary<string, ItemData>();
    private readonly Dictionary<string, int> _itemCounts = new Dictionary<string, int>();

    /// <summary>当前道具列表（只读），每种道具只出现一次</summary>
    public IReadOnlyList<ItemData> Items => _items;

    /// <summary>道具种类数量</summary>
    public int Count => _items.Count;

    // ========== 事件 ==========

    /// <summary>道具获得: (itemData)</summary>
    public event Action<ItemData> OnItemAcquired;

    /// <summary>道具移除: (itemData)</summary>
    public event Action<ItemData> OnItemRemoved;

    /// <summary>道具丢弃: (itemData, worldPosition)</summary>
    public event Action<ItemData, Vector3> OnItemDropped;

    /// <summary>道具转移: 从 (fromOwner, itemData) 转移到 (toOwner, itemData)</summary>
    public static event Action<ItemManager, ItemManager, ItemData> OnItemTransferred;

    /// <summary>任意道具被获取后触发（供 Buff 检查三件套等）</summary>
    public static event Action<GameObject> OnAnyItemAcquired;

    // ========== Unity 生命周期 ==========

    private void Start()
    {
        // Inspector 调试：自动获得初始道具
        foreach (var item in _initialItems)
        {
            if (item != null)
                AcquireItem(item);
        }
    }

    // ========== 核心方法 ==========

    /// <summary>
    /// 获得道具 — 每次获取都执行效果（支持叠加）。
    /// maxCount=0 表示无上限。
    /// </summary>
    public bool AcquireItem(ItemData item)
    {
        if (item == null) return false;

        int max = item.maxCount;
        bool hasItem = _itemDict.ContainsKey(item.itemId);
        int currentCount = hasItem ? _itemCounts[item.itemId] : 0;

        // 达到上限
        if (max > 0 && currentCount >= max)
            return false;

        // 每次获取都执行效果
        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = currentCount + 1;
        }

        OnItemAcquired?.Invoke(item);
        OnAnyItemAcquired?.Invoke(gameObject);
        return true;
    }

    /// <summary>
    /// 移除道具 — 每次移除都执行清理（支持叠加效果逐层移除）。
    /// 数量归零时从集合移除。
    /// </summary>
    public bool RemoveItem(string itemId)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次移除都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具 — 在世界坐标生成可拾取的掉落物。
    /// 与 RemoveItem 的区别：丢弃会在场景中生成 ItemPickup GameObject。
    /// </summary>
    public bool DropItem(string itemId, Vector3 worldPosition)
    {
        if (!_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 每次丢弃都执行清理
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 在世界坐标生成掉落物
        SpawnItemPickup(item, worldPosition);

        OnItemDropped?.Invoke(item, worldPosition);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>
    /// 丢弃道具在玩家脚下
    /// </summary>
    public bool DropItemAtPlayer(string itemId)
    {
        return DropItem(itemId, transform.position + (Vector3)(UnityEngine.Random.insideUnitCircle * 0.5f));
    }

    /// <summary>
    /// 将道具转移给另一个拥有者。
    /// 从当前所有者的集合移除，添加到目标所有者的集合。
    /// 用于交易 / 队友共享道具等场景。
    /// </summary>
    public bool TransferItem(string itemId, ItemManager targetOwner)
    {
        if (targetOwner == null || !_itemDict.TryGetValue(itemId, out var item))
            return false;

        // 目标不能已有同 ID 道具且已达上限
        if (targetOwner.HasItem(itemId))
        {
            int targetMax = item.maxCount;
            int targetCount = targetOwner.GetItemCount(itemId);
            if (targetMax > 0 && targetCount >= targetMax)
                return false;
        }

        // 从当前所有者移除一份
        item.effect?.OnRemove(gameObject);

        int count = _itemCounts[itemId];
        if (count <= 1)
        {
            item.effect?.OnRemove(gameObject);
            _items.Remove(item);
            _itemDict.Remove(itemId);
            _itemCounts.Remove(itemId);
        }
        else
        {
            _itemCounts[itemId] = count - 1;
        }

        // 添加到目标
        targetOwner.AcquireItemInternal(item);

        OnItemTransferred?.Invoke(this, targetOwner, item);
        OnItemRemoved?.Invoke(item);
        return true;
    }

    /// <summary>内部获得道具（供 TransferItem 使用）</summary>
    private void AcquireItemInternal(ItemData item)
    {
        bool hasItem = _itemDict.ContainsKey(item.itemId);

        item.effect?.OnAcquire(gameObject);

        if (!hasItem)
        {
            _items.Add(item);
            _itemDict[item.itemId] = item;
            _itemCounts[item.itemId] = 1;
        }
        else
        {
            _itemCounts[item.itemId] = _itemCounts[item.itemId] + 1;
        }

        OnItemAcquired?.Invoke(item);
    }

    /// <summary>是否有指定道具</summary>
    public bool HasItem(string itemId) => _itemDict.ContainsKey(itemId);

    /// <summary>获取道具</summary>
    public ItemData GetItem(string itemId)
        => _itemDict.TryGetValue(itemId, out var item) ? item : null;

    /// <summary>获取道具持有数量（不存在返回0）</summary>
    public int GetItemCount(string itemId)
        => _itemCounts.TryGetValue(itemId, out var count) ? count : 0;

    // ========== 私有方法 ==========

    /// <summary>在指定世界位置生成可拾取的道具掉落物</summary>
    private void SpawnItemPickup(ItemData item, Vector3 position)
    {
        GameObject prefab = _itemDropPrefab;
        if (prefab == null)
        {
            // 如果没有配置掉落预制体，创建一个默认的
            prefab = CreateDefaultPickup();
        }

        GameObject go = Instantiate(prefab, position, Quaternion.identity);
        go.name = $"ItemPickup_{item.itemId}";

        var pickup = go.GetComponent<ItemPickup>();
        if (pickup == null)
            pickup = go.AddComponent<ItemPickup>();
        pickup.itemData = item;
    }

    /// <summary>创建默认拾取物预制体（运行时兜底）</summary>
    private GameObject CreateDefaultPickup()
    {
        var go = new GameObject("DefaultItemPickup", typeof(SpriteRenderer), typeof(CircleCollider2D), typeof(ItemPickup));
        var sr = go.GetComponent<SpriteRenderer>();
        sr.sprite = null; // 使用默认图标
        sr.drawMode = SpriteDrawMode.Simple;
        var col = go.GetComponent<CircleCollider2D>();
        col.isTrigger = true;
        col.radius = 0.5f;
        return go;
    }
}

using UnityEngine;

/// <summary>
/// 道具拾取物 — 场景中可拾取的道具 GameObject。
///
/// 交互方式 (近距离按键):
///   1. 玩家靠近时高亮显示 + 弹出详情 UI
///   2. 按 F 键拾取
///   3. 不再通过碰撞自动拾取
/// </summary>
public class ItemPickup : MonoBehaviour
{
    [Header("道具数据")]
    public ItemData itemData;

    [Header("交互距离")]
    [Tooltip("玩家可交互的最大距离")]
    public float pickupRadius = 1.5f;

    [Header("表现")]
    public GameObject pickupEffectPrefab;

    [Header("漂浮动画")]
    [SerializeField] private bool _enableFloatAnimation = true;
    [SerializeField] private float _floatAmplitude = 0.15f;
    [SerializeField] private float _floatFrequency = 2f;
    [SerializeField] private bool _enableRotation = true;
    [SerializeField] private float _rotationSpeed = 30f;

    [Header("高亮")]
    [SerializeField] private float _highlightScale = 1.3f;
    [SerializeField] private Color _highlightTint = new Color(1f, 1f, 0.7f, 1f);

    /// <summary>当前是否在玩家交互范围内</summary>
    public bool IsInRange { get; private set; }

    /// <summary>是否为商店商品（靠近时走购买流程而非拾取）</summary>
    public bool IsShopItem { get; set; }

    /// <summary>商店价格（从 ItemData.price 读取）</summary>
    public int ShopPrice => itemData != null ? itemData.price : 10;

    private Vector3 _startPosition;
    private SpriteRenderer _spriteRenderer;
    private Color _baseColor;
    private Vector3 _baseScale;

    private void Awake()
    {
        _spriteRenderer = GetComponent<SpriteRenderer>();
        _startPosition = transform.position;
        _baseScale = transform.localScale;

        if (_spriteRenderer != null)
        {
            _baseColor = _spriteRenderer.color;

            if (itemData != null && itemData.icon != null)
                _spriteRenderer.sprite = itemData.icon;
        }
    }

    private void Update()
    {
        float t = Time.time * _floatFrequency;
        Vector3 floatOffset = _enableFloatAnimation
            ? Vector3.up * (Mathf.Sin(t) * _floatAmplitude)
            : Vector3.zero;

        // 高亮（始终运行）
        if (IsInRange)
        {
            transform.localScale = _baseScale * _highlightScale;
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_baseColor, _highlightTint, 0.5f);
        }
        else
        {
            transform.localScale = Vector3.Lerp(transform.localScale, _baseScale, Time.deltaTime * 8f);
            if (_spriteRenderer != null)
                _spriteRenderer.color = Color.Lerp(_spriteRenderer.color, _baseColor, Time.deltaTime * 8f);
        }

        // 漂浮位移（仅 _enableFloatAnimation 时生效）
        transform.position = _startPosition + floatOffset;

        // 旋转（仅 _enableRotation 时生效）
        if (_enableRotation)
            transform.Rotate(Vector3.forward, _rotationSpeed * Time.deltaTime);
    }

    /// <summary>由 ItemInteractionHandler 调用，标记在范围内</summary>
    public void SetInRange(bool inRange)
    {
        IsInRange = inRange;
    }

    /// <summary>执行拾取 — 返回道具数据</summary>
    public ItemData Pickup()
    {
        if (pickupEffectPrefab != null)
            Instantiate(pickupEffectPrefab, transform.position, Quaternion.identity);

        return itemData;
    }

    /// <summary>品质 → 颜色映射</summary>
    public static Color QualityToColor(ItemQuality quality) => quality switch
    {
        ItemQuality.Common    => new Color(0.78f, 0.78f, 0.78f),
        ItemQuality.Uncommon  => new Color(0.36f, 0.65f, 1f),
        ItemQuality.Rare      => new Color(0.68f, 0.36f, 1f),
        ItemQuality.Legendary => new Color(1f, 0.65f, 0.15f),
        _                     => Color.white
    };
}

using UnityEngine;

/// <summary>
/// 道具数据资产（ScriptableObject）— 定义一种道具的所有静态属性。
/// 右键 -> Create -> Game -> Item Data 创建。
/// 参考: 以撒的结合道具 / 崩坏星穹铁道奇物 / 明日方舟藏品。
/// </summary>
[CreateAssetMenu(fileName = "NewItem", menuName = "Game/Item Data")]
public class ItemData : ScriptableObject
{
    [Header("基本信息")]
    [Tooltip("唯一标识，如 'blood_of_martyr'")]
    public string itemId;              // 唯一标识
    public string itemName;            // 显示名称
    [TextArea] public string description;
    public Sprite icon;
    [Tooltip("品质: Common/Uncommon/Rare/Legendary")]
    public ItemQuality quality;        // 品质

    [Header("效果（策略模式）")]
    [Tooltip("拖入具体效果资产: ItemEffectBase 子类")]
    public ItemEffectBase effect;      // 道具效果策略

    [Header("商店")]
    [Tooltip("在商店购买时的 ATP 价格（0 = 不可购买）")]
    [Min(0)] public int price = 10;

    [Header("获取限制")]
    [Tooltip("可获取的数量上限。0 = 无限制，>0 = 最多持有该数量")]
    [Min(0)] public int maxCount;     // 数量上限
}

using UnityEngine;
using TMPro;

/// <summary>
/// 道具移除节点 — 玩家靠近显示提示，按 F 打开道具选择面板。
/// 玩家可选择移除一个道具（触发 OnRemove 还原效果），可移除 n 次。
/// </summary>
public class ItemRemover : MonoBehaviour
{
    [Header("配置")]
    [Tooltip("可移除道具的次数（-1=无限）")]
    [SerializeField] private int _removeCount = 1;

    [Header("交互")]
    [Tooltip("交互范围")]
    [SerializeField] private float _interactRadius = 1.5f;
    [Tooltip("交互按键")]
    [SerializeField] private KeyCode _interactKey = KeyCode.F;

    [Header("视觉")]
    [SerializeField] private SpriteRenderer _sr;
    [SerializeField] private Color _normalColor = new Color(0.8f, 0.3f, 0.3f, 1f);
    [SerializeField] private Color _highlightColor = new Color(1f, 0.5f, 0.5f, 1f);
    [SerializeField] private Color _depletedColor = new Color(0.3f, 0.3f, 0.3f, 0.5f);

    [Header("提示文本")]
    [SerializeField] private TMP_Text _promptText;

    private bool _playerInRange;
    private bool _depleted;
    private ItemRemoverPanel _panel;

    private void Awake()
    {
        if (_sr == null)
            _sr = GetComponent<SpriteRenderer>();
        UpdateVisual();
    }

    private void Start()
    {
        _panel = FindObjectOfType<ItemRemoverPanel>(true);
    }

    private void Update()
    {
        if (_depleted) return;

        var player = GameObject.FindGameObjectWithTag("Player");
        if (player == null) return;

        float dist = Vector2.Distance(transform.position, player.transform.position);
        bool inRange = dist <= _interactRadius;

        if (inRange != _playerInRange)
        {
            _playerInRange = inRange;
            UpdateVisual();
            if (_promptText != null)
                _promptText.gameObject.SetActive(inRange);
        }

        if (inRange && Input.GetKeyDown(_interactKey) && _panel != null && !_panel.IsVisible)
        {
            var itemManager = player.GetComponent<ItemManager>();
            if (itemManager != null && itemManager.Count > 0)
            {
                _panel.Show(itemManager, _removeCount, OnPanelClosed);
            }
        }
    }

    private void OnPanelClosed()
    {
        // 面板关闭后检查剩余次数
        if (_panel != null)
        {
            // 读取面板剩余次数（通过反射，避免额外接口）
            var field = typeof(ItemRemoverPanel).GetField("_remainingCount",
                System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance);
            if (field != null)
            {
                int remaining = (int)field.GetValue(_panel);
                if (_removeCount > 0)
                {
                    _removeCount = remaining;
                    if (_removeCount <= 0)
                    {
                        _depleted = true;
                        UpdateVisual();
                        if (_promptText != null)
                            _promptText.gameObject.SetActive(false);
                    }
                }
            }
        }
    }

    private void UpdateVisual()
    {
        if (_sr == null) return;

        if (_depleted)
            _sr.color = _depletedColor;
        else if (_playerInRange)
            _sr.color = _highlightColor;
        else
            _sr.color = _normalColor;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = new Color(1f, 0.3f, 0.3f, 0.3f);
        Gizmos.DrawWireSphere(transform.position, _interactRadius);
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
